  picker.value = new Date(2026, 4, 11);

  // Range objects
  picker.value = { from: '2026-05-11', to: '2026-05-18' };
  picker.value = { from: new Date(2026, 4, 11), to: new Date(2026, 4, 18) };

const picker = document.querySelector('wa-date-picker');

